            if (active.length === 0) {
              evictionSQL = ` SELECT id FROM $ { viewName } WHERE $ { departingWhereSQL } `
            } else {
              const combinedRemaining =
                active.length === 1
                  ? active[0]!
                  : or(active[0], active[1], ...active.slice(2))
