          if (wasActive) {
            pendingReleases.push({ options, failures: 0 })
            // New work must not wait for another release's backoff.
            clearTimeout(releaseRetryTimer)
            releaseRetryTimer = undefined
            scheduleReleaseDrain()
          }
        }

        markReady()

        return {
