                trackingDisposal,
                ...pendingLoads,
              ])
              const disposalSettlement = ownershipSettlements[0]

              let settledTasks = 0
              while (settledTasks < collector.tasks.length) {
                const tasks = collector.tasks.slice(settledTasks)
                settledTasks = collector.tasks.length
